INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33211, 'Luke 8:20', 'Luke', 8, 20, 'یو چا عیسی ته وویل: «ستا مور او ورونه دباندې ولاړ دي او غواړي چې تا وویني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_20.mp3', '', 1761754199, 1761754199),
(33212, 'Luke 8:21', 'Luke', 8, 21, 'عیسی په ځواب کې وویل: «زما مور او ورونه هغه دي چې د خدای کلام اوري او عمل ورباندې کوي.» عیسی توفان ودروي (متي ۸‏:‌۲۳‌‏-‌۲۷ او مرقوس ۴‏:‌۳۵‌‏-‌۴۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_21.mp3', '', 1761754199, 1761754199),
(33213, 'Luke 8:22', 'Luke', 8, 22, 'یوه ورځ عیسی د خپلو شاګردانو سره په کشتۍ کې سپور شو او هغوی ته یې وویل: «راځئ چې د بحیرې بلې غاړې ته لاړ شو.» نو هغوی روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_22.mp3', '', 1761754199, 1761754199),
(33214, 'Luke 8:23', 'Luke', 8, 23, 'کله چې هغوی په کشتۍ کې روان وو، نو عیسی ویده شو. په دې وخت کې ناڅاپه په بحیره کې سخت باد راوالوت او کشتۍ د اوبو څخه په ډکېدلو شوه او هغوی د یو لوی خطر سره مخامخ وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_23.mp3', '', 1761754199, 1761754199),
(33215, 'Luke 8:24', 'Luke', 8, 24, 'شاګردان عیسی ته ورغلل، هغه یې راویښ کړ او ورته ویې ویل: «استاذه! استاذه! مونږ ډوبیږو.» عیسی راویښ شو او باد او د اوبو څپو ته یې حکم وکړ، توفان ودرېده او هرڅه ارام شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_24.mp3', '', 1761754199, 1761754199),
(33216, 'Luke 8:25', 'Luke', 8, 25, 'بیا هغه خپلو شاګردانو ته وویل: «ستاسو ایمان څه شو؟» خو هغوی په وېره او حیرانتیا سره یو بل ته وویل: «دا سړی څوک دی چې حتی باد او اوبو ته امر کوي او هغوی یې مني؟» عیسی پېریانو نیولي سړي ته شفا ورکوي (متي ۸‏:‌۲۸‌‏-‌۳۴ او مرقوس ۵‏:‌۱‌‏-‌۲۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_25.mp3', '', 1761754199, 1761754199),
(33217, 'Luke 8:26', 'Luke', 8, 26, 'بیا عیسی د خپلو شاګردانو سره د جدریانو سیمې ته چې د جلیل ولایت ته مخامخ دی، ورسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_26.mp3', '', 1761754199, 1761754199),
(33218, 'Luke 8:27', 'Luke', 8, 27, 'څنګه چې عیسی د کشتۍ څخه راښکته شو، نو د هغه ښار د یو سړي سره چې پېریانو نیولی ؤ، مخامخ شو. زیاته موده کېدله چې هغه لوڅ ګرځېده او په کور کې نه اوسېده، بلکې په هدیره کې اوسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_27.mp3', '', 1761754199, 1761754199),
(33219, 'Luke 8:28', 'Luke', 8, 28, 'کله چې هغه عیسی ولیده، نو چیغې یې ووهلې او د هغه په پښو کې پرېوت او په لوړ اواز یې وویل: «ای عیسی، ای د خدای تعالی زویه! زما سره څه کار لرې؟ زه تاته زاري کوم، ما مه په عذابوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_28.mp3', '', 1761754199, 1761754199),
(33220, 'Luke 8:29', 'Luke', 8, 29, 'هغه ځکه داسې وویل چې عیسی پېریانو ته امر کړی ؤ چې د هغه سړي څخه راووځي. هغه سړی څو څو ځلې پېریانو نیولی ؤ. خلکو به د هغه لاسونه او پښې په زنځیرونو تړلې او ځولنې به یې ورته اچولې، خو هغه به ماتولې او پېریانو به هغه دښتې ته بیولو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_29.mp3', '', 1761754199, 1761754199),
(33221, 'Luke 8:30', 'Luke', 8, 30, 'عیسی د هغه څخه پوښتنه وکړه: «ستا نوم څه دی؟» هغه ځواب ورکړ: «زما نوم لښکر دی.» ځکه چې په هغه کې ډېر پېریان وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_30.mp3', '', 1761754199, 1761754199),
(33222, 'Luke 8:31', 'Luke', 8, 31, 'پېریانو عیسی ته زارۍ وکړې چې د ځمکې تل ته د لېږلو حکم مه راکوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_31.mp3', '', 1761754199, 1761754199),
(33223, 'Luke 8:32', 'Luke', 8, 32, 'هلته نژدې د خوګانو یوه لویه رمه وه چې په یوې غونډۍ باندې څرېدله. نو پېریانو عیسی ته زاري وکړه چې دوی ته اجازه ورکړي چې په خوګانو کې ننوځي، نو هغه ورته اجازه ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_32.mp3', '', 1761754199, 1761754199),
(33224, 'Luke 8:33', 'Luke', 8, 33, 'بیا پېریان د هغه سړي څخه ووتل او په خوګانو کې ورننوتل. ټوله رمه په منډه د کمر څخه ښکته بحیرې ته ولوېدله او ډوبه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_33.mp3', '', 1761754199, 1761754199),
(33225, 'Luke 8:34', 'Luke', 8, 34, 'کله چې د خوګانو ساتونکو دا پېښه ولیدله، نو وتښتېدل او دا خبر یې ښار او بانډو ته ورساوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_34.mp3', '', 1761754199, 1761754199),
(33226, 'Luke 8:35', 'Luke', 8, 35, 'خلک د دې پېښې د لیدلو دپاره دباندې راووتل. کله چې هغوی عیسی ته راغلل، نو هغه سړی یې ولیده چې پېریان ورڅخه وتلي وو. هغه د عیسی پښو ته ناست ؤ، کالي یې اغوستي وو او بېرته خپل عادي حالت ته راغلی ؤ، نو هغوی ووېرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_35.mp3', '', 1761754199, 1761754199),
(33227, 'Luke 8:36', 'Luke', 8, 36, 'کومو خلکو چې دا پېښه لیدلې وه هغوی نورو ته وویل چې دا سړی چې پېریانو نیولی ؤ څنګه روغ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_36.mp3', '', 1761754199, 1761754199),
(33228, 'Luke 8:37', 'Luke', 8, 37, 'بیا د جدریان د شاوخوا سیمو ټولو خلکو د عیسی څخه وغوښتل چې له هغه ځای څخه لاړ شي، ځکه چې هغوی ډېر وېرېدلي وو. نو عیسی په کشتۍ کې سپور شو چې د بحیرې بلې غاړې ته لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_37.mp3', '', 1761754199, 1761754199),
(33229, 'Luke 8:38', 'Luke', 8, 38, 'بیا هغه سړي چې پېریان ورڅخه وتلي وو عیسی ته زاري وکړه چې اجازه ورته ورکړي د هغه سره لاړ شي، خو عیسی هغه رخصت کړ او ورته ویې ویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_38.mp3', '', 1761754199, 1761754199),
(33230, 'Luke 8:39', 'Luke', 8, 39, '«بېرته خپل کور ته لاړ شه او هغه څه چې خدای ستا دپاره کړي دي هغه ټولو ته ووایه.» هغه سړی په ټول ښار کې وګرځېد او عیسی چې د هغه دپاره څه کړي وو هغه یې خلکو ته بیان کړل. د عیسی له خوا د ایمان په خاطر شفا ورکول (متي ۹‏:‌۱۸‌‏-‌۲۶ او مرقوس ۵‏:‌۲۱‌‏-‌۴۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_39.mp3', '', 1761754199, 1761754199),
(33231, 'Luke 8:40', 'Luke', 8, 40, 'کله چې عیسی بېرته راستون شو، نو خلکو ورته تود هرکلی ووایه، ځکه چې هغوی ټول ورته په انتظار وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_40.mp3', '', 1761754199, 1761754199),
(33232, 'Luke 8:41', 'Luke', 8, 41, 'بیا یو سړی چې یایروس نومېده او د یوې کنیسې مشر ؤ، راغی او د عیسی په پښو کې پرېوت او زاري یې ورته وکړه چې د هغه سره کور ته لاړ شي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_41.mp3', '', 1761754199, 1761754199),
(33233, 'Luke 8:42', 'Luke', 8, 42, 'ځکه چې د هغه یوازېنۍ لور چې دولس کلنه وه د مرګ په حالت کې پرته وه. کله چې عیسی په لاره روان ؤ، خلکو د هرې خوا ورباندې زور راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_42.mp3', '', 1761754199, 1761754199),
(33234, 'Luke 8:43', 'Luke', 8, 43, 'د هغوی په منځ کې یوه ښځه وه چې د دولسو کالو راهیسې ورڅخه وینه بهېدله. هغې خپلې ټولې پیسې په ډاکترانو لګولې وې، خو هېچا د هغې علاج نه شو کولای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_43.mp3', '', 1761754199, 1761754199),
(33235, 'Luke 8:44', 'Luke', 8, 44, 'هغه د شا له خوا راغله او د عیسی چپنې ته یې لاس وروړ او سمدلاسه یې وینه ودرېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_44.mp3', '', 1761754199, 1761754199),
(33236, 'Luke 8:45', 'Luke', 8, 45, 'عیسی پوښتنه وکړه: «چا ماته لاس راوړ؟» ټول منکر شول خو پطروس وویل: «استاذه! ټول خلک درڅخه راتاو دي او د هرې خوا درباندې زور راوړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_45.mp3', '', 1761754199, 1761754199),
(33237, 'Luke 8:46', 'Luke', 8, 46, 'خو عیسی وویل: «کوم چا راته لاس راوړ، ځکه زه پوه شوم چې زما څخه یو قوت ووت.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_46.mp3', '', 1761754199, 1761754199),
(33238, 'Luke 8:47', 'Luke', 8, 47, 'کله چې هغه ښځه پوه شوه چې پټه نه شي پاتې کېدلی نو په رپېدلو شوه، راغله او د عیسی په پښو کې پرېوتله او د ټولو په مخکې یې وویل چې ولې یې هغه ته لاس وروړ او څنګه سمدلاسه روغه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_47.mp3', '', 1761754199, 1761754199),
(33239, 'Luke 8:48', 'Luke', 8, 48, 'عیسی هغې ته وویل: «لورې! ته خپل ایمان روغه کړې. په خیر لاړه شې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_48.mp3', '', 1761754199, 1761754199),
(33240, 'Luke 8:49', 'Luke', 8, 49, 'عیسی لا خبرې کولې چې د کنیسې د مشر له کوره یو سړی راغی او یایروس ته یې وویل: «ستا لور مړه شوه، استاذ ته نور تکلیف مه ورکوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_49.mp3', '', 1761754199, 1761754199),
(33241, 'Luke 8:50', 'Luke', 8, 50, 'خو کله چې عیسی دا خبره واورېدله، نو یایروس ته یې وویل: «مه وېرېږه، یوازې ایمان ولره او هغه به راژوندۍ شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_50.mp3', '', 1761754199, 1761754199),
(33242, 'Luke 8:51', 'Luke', 8, 51, 'کله چې عیسی د یایروس کور ته ننوت نو هغه پرته له پطروس، یوحنا، یعقوب او د هغې انجلۍ د مور او پلاره بل هېچا ته اجازه ورنه کړه چې دننه ورسره لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_51.mp3', '', 1761754199, 1761754199),
(33243, 'Luke 8:52', 'Luke', 8, 52, 'ټولو د هغې انجلۍ دپاره ژړا او انګولا کوله. خو عیسی وویل: «مه ژاړئ، هغه مړه نه ده، هغه خو ویده ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_52.mp3', '', 1761754199, 1761754199),
(33244, 'Luke 8:53', 'Luke', 8, 53, 'هغوی ټولو په هغه پورې وخندل، ځکه هغوی ښه پوهېدل چې هغه مړه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_53.mp3', '', 1761754199, 1761754199),
(33245, 'Luke 8:54', 'Luke', 8, 54, 'خو عیسی هغه انجلۍ له لاسه ونیوله او ورته نارې یې کړې: «ای انجلۍ! راپاڅېږه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_54.mp3', '', 1761754199, 1761754199),
(33246, 'Luke 8:55', 'Luke', 8, 55, 'هغه بېرته راژوندۍ شوه او سمدلاسه راپاڅېدله. عیسی هغوی ته امر وکړ چې هغې ته یو څه ورکړئ چې ویې خوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_55.mp3', '', 1761754199, 1761754199),
(33247, 'Luke 8:56', 'Luke', 8, 56, 'د هغې مور او پلار ډېر حیران شول، خو عیسی هغوی ته امر وکړ چې د دې پېښې په هکله چاته څه ونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke8_verse_56.mp3', '', 1761754199, 1761754199),
(33248, 'James 5:1', 'James', 5, 1, 'واورئ ای شتمنو خلکو! د هغو مصیبتونو په خاطر چې په تاسو باندې راتلونکي دي، ژړا او انګولا وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_1.mp3', '', 1761754199, 1761754199),
(33249, 'James 5:2', 'James', 5, 2, 'ستاسو شتمني تباه شوې ده او کالي مو چینجو خوړلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_2.mp3', '', 1761754199, 1761754199),
(33250, 'James 5:3', 'James', 5, 3, 'ستاسو سره زر او سپین زر زنګ وهلي او د هغوی زنګ به په تاسو شاهدي ورکوي او د اور په شان به ستاسو بدن وسوځوي. خو بیاهم تاسو د دې نړۍ په اخرو ورځو کې مال او دولت ذخیره کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_3.mp3', '', 1761754199, 1761754199),
(33251, 'James 5:4', 'James', 5, 4, 'ګورئ، کومو خلکو چې ستاسو په پټیو کې لو کړی دی او تاسو د هغوی مزدوري نه ده ورکړې، چیغې وهي او د لوګرو فریادونه د مطلق قادر څښتن غوږونو ته رسېدلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_4.mp3', '', 1761754199, 1761754199),
(33252, 'James 5:5', 'James', 5, 5, 'تاسو په نړۍ کې په عیش او عشرت ژوند تېروئ او مزې کوئ، خو اوس تاسو د هغو حیواناتو په شان یئ چې ځانونه مو د حلالولو د ورځې دپاره چاغ کړي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_5.mp3', '', 1761754199, 1761754199),
(33253, 'James 5:6', 'James', 5, 6, 'تاسو بې‌ګناه خلک مجرمان کړل او ومو وژل او هغوی ستاسو په وړاندې ونه درېدل. په سختیو کې صبر کول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_6.mp3', '', 1761754199, 1761754199),
(33254, 'James 5:7', 'James', 5, 7, 'نو ای خویندو او ورونو! د څښتن تر راتګ پورې صبر وکړئ. ګورئ، یو بزګر څنګه د خپلې ځمکې څخه د ارزښتناکه حاصل د راټولولو په خاطر صبر کوي او د مني او پسرلي بارانونو ته انتظار وباسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_7.mp3', '', 1761754199, 1761754199),
(33255, 'James 5:8', 'James', 5, 8, 'نو تاسو هم باید صبر وکړئ او خپل زړونه قوي کړئ، ځکه چې د څښتن راتګ نژدې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_8.mp3', '', 1761754199, 1761754199),
(33256, 'James 5:9', 'James', 5, 9, 'ای خویندو او ورونو! د یو بل څخه شکایت مه کوئ، ترڅو خدای تاسو تر خپل قضاوت لاندې ونه نیسي، ځکه چې قاضي په دروازه کې ولاړ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_9.mp3', '', 1761754199, 1761754199),
(33257, 'James 5:10', 'James', 5, 10, 'ای خویندو او ورونو! کومو پیغمبرانو چې د څښتن په نوم خبرې کړې دي د هغوی صبر او کړاوونه د خپلو ځانونو دپاره مثال وګرځوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_10.mp3', '', 1761754199, 1761754199),
(33258, 'James 5:11', 'James', 5, 11, 'مونږ صبر کوونکي خلک بختور ګڼو. تاسو د ایوب د صبر په هکله اورېدلي دي او خبر یئ چې څښتن په پای کې د هغه سره څنګه مرسته وکړه، ځکه چې خدای ډېر زړه‌سواندی او مهربانه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_11.mp3', '', 1761754199, 1761754199),
(33259, 'James 5:12', 'James', 5, 12, 'ای زما خویندو او ورونو! په پای کې دا مهمه ده چې قسم ونه خورئ، نه په اسمان، نه په ځمکه او نه په کوم بل شي، بلکې ستاسو «هو» باید «هو» وي او «نه» مو «نه» وي، هسې نه چې د خدای د قضاوت لاندې راشئ. زوروره او اثرناکه دعا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_12.mp3', '', 1761754199, 1761754199),
(33260, 'James 5:13', 'James', 5, 13, 'که ستاسو څخه کوم څوک د کړاوونو سره مخامخ وي، نو دعا دې وکړي او که څوک خوشحاله وي، نو هغه دې د ستاینې سندرې ووایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_13.mp3', '', 1761754199, 1761754199),
(33261, 'James 5:14', 'James', 5, 14, 'که په تاسو کې څوک ناروغه وي، نو د کلیسا مشران دې راوغواړي چې د هغه دپاره دعا وکړي او د هغه بدن دې د څښتن په نوم په تېلو باندې غوړ کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_14.mp3', '', 1761754199, 1761754199),
(33262, 'James 5:15', 'James', 5, 15, 'کومه دعا چې په ایمان سره وشي، نو ناروغ به جوړ شي. څښتن به بېرته هغه روغ کړي او که ګناه یې کړې وي، نو هغه به ورته وبخښل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_15.mp3', '', 1761754199, 1761754199),
(33263, 'James 5:16', 'James', 5, 16, 'نو بیا یو بل ته د خپلو ګناهونو اقرار وکړئ او د یو بل دپاره دعا وکړئ چې شفا ومومئ. د نېک سړي دعا ډېره زوروره او اثرناکه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_16.mp3', '', 1761754199, 1761754199),
(33264, 'James 5:17', 'James', 5, 17, 'الیاس نبي زمونږ په شان یو انسان ؤ، خو کله یې چې د زړه له کومي دعا وکړه چې باران دې ونه وریږي، نو تر درې نیمو کلونو پورې په ځمکه باندې باران ونه شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_17.mp3', '', 1761754199, 1761754199),
(33265, 'James 5:18', 'James', 5, 18, 'هغه یوځل بیا دعا وکړه او د اسمان څخه باران وشو او په ځمکه کې فصل پیدا شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_18.mp3', '', 1761754199, 1761754199),
(33266, 'James 5:19', 'James', 5, 19, 'ای زما خویندو او ورونو! که په تاسو کې څوک د رښتینې لارې څخه واوړي او بل څوک هغه بېرته راوګرځوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james5_verse_19.mp3', '', 1761754199, 1761754199),
