(33268, 'Romans 12:1', 'Romans', 12, 1, 'نو له دې امله ای خویندو او ورونو! زه د خدای د رحمتونو په خاطر ستاسو نه غوښتنه کوم چې خپل ځانونه خدای ته د ژوندۍ او سپېڅلې قربانۍ په توګه چې هغه ته د منلو وړ وي، وړاندې کړئ. دا ستاسو رښتینی او مناسب عبادت دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_1.mp3', '', 1761754199, 1761754199),
(33269, 'Romans 12:2', 'Romans', 12, 2, 'د دې دنیا په شان مه کېږئ، بلکې پرېږدئ چې د خپلو فکرونو په نوي کولو سره خدای تاسو بدل کړي. بیا به تاسو وکولای شئ چې د خدای اراده وپېژنئ او هغه څه چې ښه، د منلو وړ او کامل دي، وپېژنئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_2.mp3', '', 1761754199, 1761754199),
(33270, 'Romans 12:3', 'Romans', 12, 3, 'د هغه فضل له مخې چې ماته راکړل شوی دی، زه تاسو هر یو ته وایم چې خپل ځان لکه څنګه چې اوس یئ، د دې نه لوړ مه ګنئ. بلکې عاجز اوسئ او د هغه ایمان د اندازې له مخې چې خدای تاسو هر یو ته درکړی دی، فکر وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_3.mp3', '', 1761754199, 1761754199),
(33271, 'Romans 12:4', 'Romans', 12, 4, 'لکه څنګه چې زمونږ په بدن کې ډېر غړي دي او د ټولو غړو کار یوشان نه دی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_4.mp3', '', 1761754199, 1761754199),
(33272, 'Romans 12:5', 'Romans', 12, 5, 'نو مونږ چې ډېر یو، خو په مسیح کې یو بدن یو او د یو بل غړي یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_5.mp3', '', 1761754199, 1761754199),
(33273, 'Romans 12:6', 'Romans', 12, 6, 'مونږ باید د هغو مختلفو نعمتونو څخه چې خدای راته د خپل فضل له مخې راکړي دي، کار واخلو. که چېرې هغه د خدای د پیغام رسول وي، نو هغه باید د خپل ایمان له مخې سرته ورسوو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_6.mp3', '', 1761754199, 1761754199),
(33274, 'Romans 12:7', 'Romans', 12, 7, 'که خدمت کول وي، نو باید خدمت وکړو. که هغه تعلیم ورکول وي، نو باید تعلیم ورکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_7.mp3', '', 1761754199, 1761754199),
(33275, 'Romans 12:8', 'Romans', 12, 8, 'که هغه د نورو هڅول وي، نو باید ویې هڅوو. که چېرې د مالي مرستې ورکول وي، نو د سخاوت له مخې یې ورکړو، که چېرې د مشرۍ نعمت وي نو په کوښښ سره یې وکړو، که چېرې د مهربانۍ کولو نعمت وي، نو په خوشحالۍ سره رحم وکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_8.mp3', '', 1761754199, 1761754199),
(33276, 'Romans 12:9', 'Romans', 12, 9, 'ستاسو مینه دې رښتینې او سوچه وي. د بدو نه کرکه کوئ او په نېکۍ کې ټینګ ودرېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_9.mp3', '', 1761754199, 1761754199),
(33277, 'Romans 12:10', 'Romans', 12, 10, 'یو د بل سره د ورورولۍ مینه کوئ او هر یو دې د خپل ځان نه زیات د نورو درناوی وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_10.mp3', '', 1761754199, 1761754199),
(33278, 'Romans 12:11', 'Romans', 12, 11, 'په خپل کار کې تنبلي مه کوئ او په روحاني شوق سره د څښتن خدمت کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans12_verse_11.mp3', '', 1761754199, 1761754199),
